/*
 * Replaces the theme's caching service worker. Browsers that still have the old
 * worker pick this one up on their next update check; it then clears every cache,
 * unregisters itself and reloads open tabs so they come straight from the network.
 */
self.addEventListener('install', function () {
  self.skipWaiting();
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    caches.keys()
      .then(function (keys) {
        return Promise.all(keys.map(function (key) { return caches.delete(key); }));
      })
      .then(function () { return self.registration.unregister(); })
      .then(function () { return self.clients.matchAll({ type: 'window' }); })
      .then(function (windows) {
        windows.forEach(function (client) { client.navigate(client.url); });
      })
  );
});
